#include <stdio.h>
int a[26]; 
void array(int a[],int k)
{
    int i;
    for(i=0;i<k;i++)
    {
        printf("%c\n",a[i]+96);
    }
}
void wellOrderdStrings(int a[],int n,int k,int i)
{
    int j;
    if(i==k)
    {
        array(a,k);
    }
    else if(i<k)
    {
        for(j=(i>0)?a[i-1]+1:1;j<=n;j++)
        {
            a[i]=j;
            wellOrderdStrings(a,n,k,i+1);    
        }
    }
}
int main()
{
    int n,k,i=0;
    scanf("%d%d",&n,&k);
    wellOrderdStrings(a,n,k,i);
    return 0;
}
